CREATE TABLE IF NOT EXISTS coupons (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(50) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255) NULL,
 discount_type ENUM('percentage','flat') NOT NULL, discount_value DECIMAL(12,2) NOT NULL, minimum_cart_amount DECIMAL(12,2) NOT NULL DEFAULT 0, maximum_discount_amount DECIMAL(12,2) NULL,
 starts_at TIMESTAMP NULL, expires_at TIMESTAMP NULL, usage_limit_total INT UNSIGNED NULL, usage_limit_per_customer INT UNSIGNED NULL, usage_count INT UNSIGNED NOT NULL DEFAULT 0, first_order_only TINYINT(1) NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL,
 PRIMARY KEY(id), UNIQUE KEY uq_coupons_code(code), KEY idx_coupons_active(is_active,deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS gift_cards (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, code_hash CHAR(64) NOT NULL, code_last4 CHAR(4) NOT NULL, initial_value DECIMAL(12,2) NOT NULL, current_balance DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'INR', status ENUM('active','disabled','exhausted') NOT NULL DEFAULT 'active', expires_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, PRIMARY KEY(id), UNIQUE KEY uq_gift_cards_hash(code_hash)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS gift_card_transactions (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, gift_card_id BIGINT UNSIGNED NOT NULL, transaction_type ENUM('issue','redeem','refund','adjustment') NOT NULL, amount DECIMAL(12,2) NOT NULL, balance_before DECIMAL(12,2) NOT NULL, balance_after DECIMAL(12,2) NOT NULL, reference_type VARCHAR(50) NULL, reference_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY idx_gift_tx_card(gift_card_id), CONSTRAINT fk_gift_tx_card FOREIGN KEY(gift_card_id) REFERENCES gift_cards(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS shipping_methods (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, code VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(255) NULL, fee DECIMAL(12,2) NOT NULL DEFAULT 0, free_shipping_threshold DECIMAL(12,2) NULL, estimated_days_min TINYINT UNSIGNED NOT NULL, estimated_days_max TINYINT UNSIGNED NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uq_shipping_code(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS coupon_redemptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, coupon_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NULL, order_id BIGINT UNSIGNED NULL, discount_amount DECIMAL(12,2) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), CONSTRAINT fk_coupon_redemption_coupon FOREIGN KEY(coupon_id) REFERENCES coupons(id) ON DELETE CASCADE)
ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
